    'asterisk_settings.rtp_section_title' => 'Setări RTP (media)',
    'asterisk_settings.rtp_help_body' => 'Controlează intervalul de porturi care transportă audio (RTP) și dacă Asterisk respinge audio sosit dintr-o sursă neașteptată. Acest fișier (<code>/etc/asterisk/rtp.conf</code>) este acum generat de panou; modificările manuale de pe server se pierd la următoarea „Aplicare”.',
    'asterisk_settings.field_rtp_start' => 'Port de început RTP',
    'asterisk_settings.rtp_start_help' => 'Începutul intervalului de porturi rezervat fluxurilor audio. Fiecare apel simultan consumă porturi din acest interval.',
    'asterisk_settings.field_rtp_end' => 'Port de sfârșit RTP',
    'asterisk_settings.rtp_end_help' => 'Sfârșitul intervalului. coturn (releu TURN) folosește 13479-14999 — o suprapunere strică audio WebRTC și este respinsă la salvare.',
    'asterisk_settings.field_rtp_strict' => 'RTP strict (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Când este activat, Asterisk elimină în mod silențios audio sosit din orice sursă alta decât adresa/portul la distanță învățat (protecție împotriva atacurilor). Dacă PBX-ul partener trimite media de pe un port neașteptat, acest lucru provoacă o defecțiune silențioasă de tip „fără audio”, fără nicio urmă în jurnale — poate fi dezactivat temporar pentru diagnosticare.',
    'asterisk_settings.rtp_strict_yes' => 'Activat (recomandat)',
    'asterisk_settings.rtp_strict_no' => 'Dezactivat (pentru diagnosticare)',
    'asterisk_settings.rtp_restart_warning' => 'Setarea RTP strict intră în vigoare la „Aplicare”. O modificare a INTERVALULUI DE PORTURI necesită însă o repornire completă a Asterisk — rezerva de porturi este alocată o singură dată, la încărcarea modulului.',
    'asterisk_settings.udptl_section_title' => 'Setări T.38 UDPTL (media fax)',
    'asterisk_settings.udptl_help_body' => 'Definește intervalele de porturi UDP și parametrii de corecție a erorilor (FEC / Checksum) pentru pachetele de fax T.38 (UDPTL). Acest fișier (<code>/etc/asterisk/udptl.conf</code>) este gestionat dinamic.',
    'asterisk_settings.field_udptl_start' => 'Port de început UDPTL',
