    'trunks.field_connection_mode' => 'Mod de conectare',
    'trunks.connection_mode_ip' => 'Bazat pe IP (partenerul are IP static)',
    'trunks.connection_mode_register' => 'Înregistrare de intrare (partenerul se înregistrează la noi)',
    'trunks.connection_mode_help' => 'Bazat pe IP: partenerul este identificat după adresa IP, iar contactul său este păstrat static — modul recomandat pentru un partener cu IP fix în aceeași rețea. Înregistrare de intrare: partenerul ne trimite un SIP REGISTER, iar adresa sa este învățată din această înregistrare. Acest mod necesită un nume de utilizator și o parolă; partenerul își autentifică cu ele atât înregistrarea, cât și apelurile.',
