    'sound_packs.title' => 'Pachete oficiale de sunete Asterisk',
    'sound_packs.help_title' => 'Pachete de sunete Asterisk',
    'sound_packs.help_body' => 'Descarcă și instalează mesajele de sistem și muzica în așteptare oficiale ale Asterisk de pe <code>downloads.asterisk.org</code>. Fiecare pachet reprezintă o limbă într-un format; Asterisk redă formatul care corespunde codecului apelului, altfel transcodează (g722 pentru G.722, ulaw/alaw pentru operatori).<br>- <strong>Core:</strong> mesaje de sistem, cifre, mesagerie vocală. <strong>Extra:</strong> mesaje suplimentare; pachetul core pentru aceeași limbă trebuie instalat mai întâi.<br>- <strong>Muzică în așteptare (opsound):</strong> se instalează în <code>/var/lib/asterisk/moh/opsound</code>; pentru a o reda, creați o clasă MOH numită <strong>opsound</strong> în fila Muzică în așteptare.<br>- <strong>Türkçe (AiPBX):</strong> mesajele proprii în limba turcă ale AiPBX (versiune GitHub, verificate SHA256); limba implicită este turca, așa că eliminarea lor dezactivează mesajele de sistem. Eliminarea șterge doar fișierele instalate de pachet.',
