    'certificates.help_title' => 'Ghid certificate',
    'certificates.help_body' => 'Portalul (HTTPS), WebRTC TURNS și SIP-TLS/WSS folosesc un singur certificat comun; modificările de aici sunt aplicate împreună pentru Apache, coturn și Asterisk. <b>Let\'s Encrypt</b> este gratuit și se reînnoiește singur; domeniul trebuie să indice spre acest server, iar portul 80 trebuie să fie accesibil din internet. Dacă organizația dvs. are un certificat, <b>încărcați-l</b> (PEM sau PFX); certificatele încărcate nu se reînnoiesc automat, încărcați unul nou înainte de expirare. Cu un certificat <b>autosemnat</b>, browserele afișează un avertisment, iar TURNS nu funcționează în browsere: apelurile WebRTC din spatele firewallurilor pot rămâne fără sunet.',
