    'queue_reports.help_title' => 'Ghid rapoarte cozi',
    'queue_reports.help_body' => 'Fiecare apel care intră într-o coadă este numărat o singură dată. <b>Preluate</b>: conectate la un agent. <b>Pierdute</b>: apelantul a închis în timp ce aștepta sau a expirat timpul cozii. <b>Abandon scurt</b>: a închis în maximum %d secunde; exclus din nivelul de serviciu. <b>Nivel de serviciu</b>: apelurile preluate în timpul țintă, raportate la toate apelurile, cu excepția abandonurilor scurte. <b>ASA</b>: timpul mediu de așteptare al apelurilor preluate. <b>AHT</b>: durata medie a convorbirii. <b>Rată de preluare</b> (agent): cât de des a răspuns agentul când coada l-a sunat. <b>Reapelare</b>: un apel pierdut este considerat rezolvat când numărul său a fost apelat ulterior de pe un interior sau a sunat din nou și a fost preluat. Datele provin din jurnalul de cozi Asterisk; raportul poate fi descărcat ca PDF sau Excel.',
