    'ai_tts.title' => 'Cloud TTS (text în vorbire)',
    'ai_tts.help_title' => 'Ghid Cloud TTS',
    'ai_tts.help_body' => 'Transformă textul în vorbire naturală cu servicii cloud (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Ascultați rezultatul, descărcați-l ca MP3 sau salvați-l ca <b>anunț</b> cu un singur clic: este convertit în formatul Asterisk (WAV 8 kHz) și adăugat în Sunete &amp; anunțuri pentru IVR-uri, rute de intrare și condiții de timp (intră în vigoare după Aplicare). <b>Aceste servicii sunt plătite</b> și se facturează pe caracter; fiecare sinteză este păstrată în istoric cu numărul de caractere. Cheile de acces provin din consola fiecărui furnizor, sunt stocate criptat și nu mai sunt afișate niciodată pe pagină.',
