    'push.help_intro' => 'Softphone-ul mobil AI PBX are o <strong>arhitectură de notificări pe straturi</strong>:',
    'push.help_layer0' => '<strong>Stratul 0 (fără dependențe - implicit):</strong> o conexiune WSS persistentă, un serviciu în prim-plan <code>specialUse</code> compatibil cu Android 15 și un watchdog <code>AlarmManager</code> rezistent la Doze care îl repornește. Nu este necesar niciun serviciu extern; apelurile sosesc chiar și când dispozitivul este inactiv sau ecranul este stins.',
    'push.help_layer1' => '<strong>Stratul 1 (opțional - Google FCM):</strong> o garanție suplimentară de trezire pe dispozitivele OEM cu restricții agresive de baterie (Xiaomi, Huawei...) sau când utilizatorul a închis aplicația prin glisare. <em>Se declanșează doar când interiorul nu are o înregistrare SIP activă, deci interioarele înregistrate nu observă nicio întârziere.</em>',
