    'storage.help_title' => 'Unde sunt păstrate fișierele de chat',
    'storage.help_body' => '<p>Atașamentele de chat, miniaturile lor și imaginile grupurilor sunt stocate implicit pe discul serverului (<code>/var/lib/aipbx/chat_files</code>). Cu o stocare compatibilă S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) ele ajung într-un bucket, iar fișierele mari nu mai stau pe PBX.</p><p>Descărcările trec în continuare prin serviciul de chat, astfel încât doar participanții unui chat îi pot deschide fișierele; bucket-ul poate rămâne privat. Fișierele stocate înainte de schimbare sunt servite în continuare de pe disc până când le mutați. Setările bucket-ului sunt verificate înainte de salvare.</p><p>Înregistrările apelurilor, mesageria vocală și faxurile rămân pe discul local.</p>',
